export const atividades: Atividade[] = linhas.map(([id, setor, nome, autonomia, fase, horas, risco]) => ({ id, setor, nome, autonomia, fase, horas, risco: risco === 1 }))
const porId = new Map(atividades.map((a) => [a.id, a]))
export const atividade = (id?: string | null) => (id ? porId.get(id) : undefined)
/** Nome curto da atividade (até a primeira vírgula ou 60 letras). */
export const nomeCurtoAtividade = (id?: string | null) => {
  const a = atividade(id)
  if (!a) return ''
  const n = a.nome.split(/[,(;]/)[0].trim()
  return n.length > 60 ? `${n.slice(0, 57)}…` : n
}
export const rotuloAutonomia: Record<Autonomia, string> = { S: 'faz sozinho', P: 'prepara, pessoa conclui', O: 'organiza e lembra' }
